  ui_story_31780401_90_dialog_content = "Eso es cierto... pero parece que ha perdido un poco de energía.",
  ui_story_31780401_91_dialog_content = "Después de todo, diez días es demasiado poco, por lo que fue muy difícil domarlo.",
  ui_story_31780401_92_dialog_content = "No fue fácil para mí alcanzar este nivel de obediencia. Tuve que hacer pleno uso de mi comprensión de los hábitos de Peko Rabbit.",
  ui_story_31780401_93_dialog_content = "¡Pero el otro Peko solo tardó dos días en recuperar completamente su vitalidad!",
  ui_story_31780401_94_dialog_content = "Se volvió muy amable y jugó con todos los Aurorianos en el Coloso.",
  ui_story_31780401_95_dialog_content = "Hablar es barato. Echémosle un vistazo.",
  ui_story_31780401_96_dialog_content = "Entonces, joven, ¿dónde está tu Peko?",
  ui_story_31780401_97_dialog_content = "Lo dejo ir.",
  ui_story_31780401_98_dialog_content = "¿Qué? ¿¡Lo dejaste ir!?",
  ui_story_31780401_99_dialog_content = "¿Eh? ¿¡Por qué!? ¡Es obvio que hubieras ganado la apuesta, Vic!",
  ui_story_31780401_100_dialog_content = "No quería participar en esto desde el principio.",
  ui_story_31780401_101_dialog_content = "¿Cuál es el punto de golpear a un anciano? Ni siquiera había dinero en juego.",
  ui_story_31780401_102_dialog_content = "...",
  ui_story_31780401_103_dialog_content = "Entonces, tomaste el Peko para poder...",
  ui_story_31780401_104_dialog_content = "Lo sé todo sobre esos nobles de Lumopolis que afirman que les gustan las bestias maravillosas.",
  ui_story_31780401_105_dialog_content = "Después de todo, solíamos tratar con ellos todo el tiempo.",
  ui_story_31780401_106_dialog_content = "Se deshacen de sus maravillosas bestias cada vez que se convierten en un pequeño inconveniente para ellos.",
  ui_story_31780401_107_dialog_content = "No hay forma de que pueda dejar que vuelva a ese tipo de vida.",
  ui_story_31780401_108_dialog_content = "Tienes un punto.",
  ui_story_31780401_109_dialog_content = "Te das cuenta de que podría denunciarte ante el Salón de Justicia de Lumopolis por lo que has hecho, ¿verdad?",
  ui_story_31780401_110_dialog_content = "Meh, realmente no me importa. Puedo dormir y escribir absolutamente en cualquier lugar.",
  ui_story_31780401_111_dialog_content = "Pero si tu noble amigo se enterara de que usaste su \"propiedad privada\" para realizar una competencia sin su permiso...",
  ui_story_31780401_112_dialog_content = "y que perdiste uno, mientras que el otro fue domesticado a un nivel inferior al estándar...",
  ui_story_31780401_113_dialog_content = "Pues bien, me temo que tanto tu amistad como tu reputación pueden estar en peligro.",
  ui_story_31780401_114_dialog_content = "¿Qué estás diciendo?",
  ui_story_31780401_115_dialog_content = "Peko-peko!",
  ui_story_31780401_116_dialog_content = "¿Peko?",
  ui_story_31780401_117_dialog_content = "Peko.",
  ui_story_31780401_118_dialog_content = "Peko!",
  ui_story_31780401_119_dialog_content = "Peko-peko.",
  ui_story_31780401_120_dialog_content = "Peko! Peko-peko!",
  ui_story_31780401_121_dialog_content = "¡Guau! ¡Vic puede hablar Peko!",
  ui_story_31780401_122_dialog_content = "Y este Peko parece tan feliz, ¡incluso se acercó a él y se frotó contra sus manos!",
  ui_story_31780401_123_dialog_content = "Es... Es un...",
  ui_story_31780401_124_dialog_content = "Si ni siquiera pudiste llegar tan lejos en diez días, supongo que todavía tienes mucho que aprender.",
  ui_story_31780401_125_dialog_content = "Es más fácil comunicarse con bestias maravillosas que con animales ordinarios porque tienen mente propia.",
  ui_story_31780401_126_dialog_content = "Es fácil ganarse su confianza siempre y cuando domines el arte de comunicarte con ellos.",
  ui_story_31780401_127_dialog_content = "...",
  ui_story_31780401_128_dialog_content = "Joven, ¿quién eres?",
  ui_story_31780401_129_dialog_content = "¿Yo? El nombre es Vic.",
  ui_story_31780401_130_dialog_content = "Vic? ¿Por qué suena tan familiar?",
  ui_story_31780401_131_dialog_content = "Espera, ¿no me digas que eres...?",
  ui_story_31780401_132_dialog_content = "¿Eres el autor del libro \"1.001 Criaturas Fantásticas\"? ¿Ese famoso extrozoólogo?",
  ui_story_31780401_133_dialog_content = "Sí, sí, ese soy yo.",
  ui_story_31780401_134_dialog_content = "No me di cuenta de que estaba en presencia de un verdadero maestro.",
  ui_story_31780401_135_dialog_content = "¡Alguien que puede comunicarse con bestias maravillosas a una edad tan temprana!",
  ui_story_31780401_136_dialog_content = "Bueno, no te sientas tan mal.",
  ui_story_31780401_137_dialog_content = "No eres mucho mayor que yo.",
  ui_story_31780401_138_dialog_content = "...",
  ui_story_31780401_139_dialog_content = "No estoy muy seguro de lo que estás hablando, pero... de todos modos, pensaré en una forma de solucionar el problema de que dejes ir a uno de los conejos.",
  ui_story_31780401_140_dialog_content = "Mientras estés dispuesto a enseñarme cómo comunicarme con bestias maravillosas.",
  ui_story_31780401_141_dialog_content = "Sin problema.",
  ui_story_31780401_142_dialog_content = "Puedes encontrarme en la clínica de animales en Umbraton la mayoría de los días.",
  ui_story_31780401_143_dialog_content = "Entonces es un trato. Vendré a visitarte en el futuro.",
  ui_story_31780401_144_dialog_content = "Todavía tengo que ir a Lumopolis hoy, así que me despediré.",
  ui_story_31780401_145_dialog_content = "Wow, ese viejo era tan superficial. ¡Su actitud cambió por completo tan pronto como descubrió quién eras!",
  ui_story_31780401_146_dialog_content = "¿No tienes ningún problema con que le devuelva ese otro Peko al noble?",
  ui_story_31780401_147_dialog_content = "qué más podemos hacer? Los pekos no son baratos.",
  ui_story_31780401_148_dialog_content = "Ya dejé pasar uno. Eso es técnicamente suficiente para que termine en la prisión de Lumopolis durante un año.",
  ui_story_31780401_149_dialog_content = "Hmm... Buen punto.",
  ui_story_31780401_150_dialog_content = "¿Pero por qué domesticaste a ese Peko para él, Vic?",
  ui_story_31780401_151_dialog_content = "Solo imaginarlo tomando el crédito por tu trabajo me hierve la sangre...",
  ui_story_31780401_152_dialog_content = "Me importa un bledo ese viejo.",
  ui_story_31780401_153_dialog_content = "Pero si ese Peko muerde a alguien de nuevo, seguro que lo matarán.",
  ui_story_31780401_154_dialog_content = "Era inevitable si no hubiera intervenido, considerando cómo se veía.",
  ui_story_31780401_155_dialog_content = "¡Ya veo!",
  ui_story_31780401_156_dialog_content = "Domaste al Peko para asegurarte de que sobreviviera.",
  ui_story_31780401_157_dialog_content = "Tengo que decir, Vic, ¡realmente me impresionaste hoy!",
  ui_story_31780401_158_dialog_content = "Por cierto, nunca supe que trabajabas en una clínica de animales.",
  ui_story_31780401_159_dialog_content = "Hah, realmente puedes ser bastante ingenuo a veces.",
  ui_story_31780401_160_dialog_content = "¿Eh?",
  ui_story_31780401_161_dialog_content = "Eso fue solo una pequeña mentira: no quiero volver a ver a ese tipo nunca más.",
  ui_story_31780401_162_dialog_content = "Ya tengo las manos ocupadas con Fia y Shira. No podía soportar que otro aprendiz como él me arrastrara hacia abajo.",
  ui_story_31780401_163_dialog_content = "PlayerName, todavía eres demasiado joven para entender completamente las formas del mundo...",
  ui_story_31780401_164_dialog_content = "... Supongo que lo soy.",
  ui_story_31780601_1_dialog_content = "<color=#e8d9bb>Agh...</color>",
  ui_story_31780601_2_dialog_content = "Oye, ¿qué es ese sonido? ¿Estás percibiendo algo con esos sentidos especiales tuyos?",
  ui_story_31780601_3_dialog_content = "¡Ese es el sonido de mi estómago gruñendo!",
  ui_story_31780601_4_dialog_content = "Yo también tengo hambre... Ya hemos terminado todas las raciones secas que trajimos con nosotros.",
  ui_story_31780601_5_dialog_content = "¿¡Y todavía tienes hambre?! ¡No puedo creer que te hayas comido todas las raciones tú solo!",
  ui_story_31780601_6_dialog_content = "¿Eh? ¿Y cuándo afirmas que hice eso? Hic—",
  ui_story_31780601_7_dialog_content = "¡Cuando estaba ocupado intentando detectar el tesoro!",
  ui_story_31780601_8_dialog_content = "Jeje, ¿así que me viste, eh? Extraño... Incluso esperé hasta que le diste la espalda.",
  ui_story_31780601_9_dialog_content = "¿Tienes idea de lo ruidoso que es tu masticar?!",
  ui_story_31780601_10_dialog_content = "Bueno, he estado tratando de mantenerte motivado todo este tiempo, chico. ¡Es agotador!",
  ui_story_31780601_11_dialog_content = "¿Eh? ¡Aún no he escuchado ni una palabra de motivación de ti!",
  ui_story_31780601_12_dialog_content = "Te he estado animando... en mi corazón.",
  ui_story_31780601_13_dialog_content = "... Si pudiera volver atrás en el tiempo, de ninguna manera elegiría ir al mar contigo, Vic.",
  ui_story_31780601_14_dialog_content = "<color=#e8d9bb>Unas horas antes...</color>",
  ui_story_31780601_15_dialog_content = "Oh, ¿no son Vic y Shira allá adelante? Hace tiempo que no nos vemos. Probablemente debería acercarme y saludar.",
  ui_story_31780601_16_dialog_content = "—No estoy realmente de humor.",
  ui_story_31780601_17_dialog_content = "¡Es el tesoro de toda una vida! Una vez que lo tengamos en nuestras manos, todos recibirán una parte igual, y eso también te incluye a ti, mi pequeño!",
  ui_story_31780601_18_dialog_content = "Bueno... que tengas un buen viaje.",
  ui_story_31780601_19_dialog_content = "¿No te importa tu maestro en absoluto? Solo piensa en mí en esos mares traicioneros y solitario: ¡el peligro, el horror! ¿Y qué pasa si un monstruo marino ataca? ¡Necesito que estés allí para ayudarme a cuidar este tipo de cosas!",
  ui_story_31780601_20_dialog_content = "Por supuesto. Esa es aún más razón por la que deberías ir por tu cuenta.",
  ui_story_31780601_21_dialog_content = "Ustedes dos realmente tienen una relación extraña para ser maestro y discípulo...",
  ui_story_31780601_22_dialog_content = "PlayerName! ¡Genial! ¡Vamos a surcar los mares juntos!",
  ui_story_31780601_23_dialog_content = "¿Golpear el qué ahora?",
  ui_story_31780601_24_dialog_content = "¡Los mares altos, muchacho! ¿Debes haber escuchado los rumores? ¡El tesoro perdido del Rey Pirata ha resurgido una vez más!",
  ui_story_31780601_25_dialog_content = "El todopoderoso Rey Pirata saqueó innumerables tesoros en su tiempo y los escondió en un lugar misterioso que solo los exploradores más valientes e inteligentes podrían encontrar.",
  ui_story_31780601_26_dialog_content = "Esto suena como una historia de uno de los libros ilustrados de Fia...",
  ui_story_31780601_27_dialog_content = "Una fuente confiable me ha informado que este alijo de tesoros dorados se encuentra en lo profundo de las olas del océano.",
  ui_story_31780601_28_dialog_content = "No estoy tan seguro de eso, quiero decir, sé cuál es tu definición de confiable...",
  ui_story_31780601_29_dialog_content = "Soy solo un anciano solitario tratando de criar a dos adorables aprendices por mi cuenta: mis piernas están grises, mis oídos están nudosos, mis ojos son viejos y torcidos.",
  ui_story_31780601_30_dialog_content = "¡Has estado perezoso todo el tiempo! Fia y yo somos los que nos encargamos de cuidarte a TI!",
  ui_story_31780601_31_dialog_content = "Ejem, bueno, ahora que finalmente tengo información sobre el tesoro, estoy listo para enfrentar una serie de trampas piratas si es necesario, todo para ganar un poco de dinero para la leche de mi querido niño, Fia!",
  ui_story_31780601_32_dialog_content = "Fia ya no es un bebé que toma leche.",
  ui_story_31780601_33_dialog_content = "PlayerName, seguramente puedes entender, teniendo que cuidar de un Colossus tan enorme y todo. Es como tener un agujero en el bolsillo, ¡y yo tengo dos!",
  ui_story_31780601_34_dialog_content = "Bueno, ahora que lo mencionas... De hecho, quería mejorar el Colossus recientemente, pero no pude conseguir los fondos para hacerlo realidad...",
  ui_story_31780601_35_dialog_content = "Pero con tus habilidades psíquicas únicas, ¡seguro que encontraremos el tesoro en muy poco tiempo! ¡Botín dorado, allá vamos!",
  ui_story_31780601_36_option_content = "¡Muéstrame el botín!",
  ui_story_31780601_37_dialog_content = "Shira, tú espera aquí, ¡volveremos con la mercancía antes de que te des cuenta!",
  ui_story_31780601_38_option_content = "¿Puedo quedarme con todo el tesoro para mí?",
  ui_story_31780601_39_dialog_content = "Justo lo que esperaría de un Caelestite: detectaste el aroma genuino de las intenciones más sinceras de mi corazón.",
  ui_story_31780601_40_dialog_content = "...",
  ui_story_31780601_41_dialog_content = "Bostezo... Solo asegúrate de volver con vida.",
  ui_story_31780601_42_dialog_content = "Según mi fuente, el tesoro debería estar ubicado en esta área del mar. ¿Me estás diciendo que realmente no puedes sentir nada aquí en absoluto?",
  ui_story_31780601_43_dialog_content = "No, nada. Tal vez esta área es demasiado grande o profunda... tal vez mis habilidades psíquicas son demasiado débiles, o tal vez... el tesoro simplemente no existe.",
  ui_story_31780601_44_dialog_content = "Me muero de hambre... y de sed aquí... Vamos a regresar...",
  ui_story_31780601_45_dialog_content = "¡Mira! ¡Hay una luz brillando en el agua!",
  ui_story_31780601_46_dialog_content = "La luz se dirige hacia nosotros. ¿Son... medusas?",
  ui_story_31780601_47_dialog_content = "No pensé que nos encontraríamos con este tipo de medusa aquí.",
  ui_story_31780601_48_dialog_content = "¿Es esto algún tipo de especie rara? La luz que emiten parece ser muy diferente a cualquier cosa que haya visto antes.",
  ui_story_31780601_49_dialog_content = "De hecho, no son medusas comunes. De hecho, ¡estas criaturas milagrosas incluso podrían llevarnos al tesoro!",
  ui_story_31780601_50_dialog_content = "Mira, es casi como si sacaran sus cabezas del agua para saludar.",
  ui_story_31780601_51_dialog_content = "¡Hola, pequeña medusa adorable! ¿Cómo estás hoy?",
  ui_story_31780601_52_dialog_content = "¡Cuidado! ¡Estas medusas son venenosas! Solo un toque y—",
  ui_story_31780601_53_dialog_content = "Es tan suave... tan liso... tan... urgh...",
  ui_story_31780601_54_dialog_content = "¡Oye, por qué lo tocaste?!",
  ui_story_31780601_55_dialog_content = "...",
  ui_story_31780601_56_dialog_content = "...",
  ui_story_31780601_57_dialog_content = "PlayerName... Despierta, PlayerName.",
  ui_story_31780601_58_dialog_content = "Urgh... ¿Qué pasó?",
  ui_story_31780601_59_dialog_content = "Te desmayaste por la picadura de una medusa, luego el banco de medusas arrastró nuestra balsa hasta aquí.",
  ui_story_31780601_60_dialog_content = "Está muy oscuro aquí. ¿Dónde estamos?",
  ui_story_31780601_61_dialog_content = "Parece ser una cueva secreta de algún tipo. ¡Creo que aquí puede estar escondido el tesoro!",
  ui_story_31780601_62_dialog_content = "No veo ningún tesoro por aquí, pero definitivamente puedo sentir una presencia peligrosa a nuestro alrededor.",
  ui_story_31780601_63_dialog_content = "Mientras yo esté aquí, puedes reírte frente al peligro.",
  ui_story_31780601_64_dialog_content = "Si realmente no tenemos nada que temer, ¿por qué te escondes detrás de mí?",
  ui_story_31780601_65_dialog_content = "Bueno, eso es porque simplemente no es muy seguro aquí, ¿verdad?",
  ui_story_31780601_66_dialog_content = "...",
  ui_story_31780601_67_dialog_content = "Jeje, solo bromeaba. Estarás a salvo, a salvo en las capaces manos de un valiente extrozoólogo extraordinario.",
  ui_story_31780601_68_dialog_content = "Todo lo que necesito hacer es invocar a mis bestias maravillosas, y enfrentemos a los malvados enemigos que sea, nunca tendremos que temer, ¡ni siquiera por un segundo!",
  ui_story_31780601_69_dialog_content = "¿Dónde están tus amigos, las bestias maravillosas? ¿Por qué no los has invocado ya?",
  ui_story_31780601_70_dialog_content = "Ah, bueno, la señal aquí no es tan buena...",
  ui_story_31780601_71_dialog_content = "¡Kree-Kree-!",
  ui_story_31780601_72_dialog_content = "¡Ah! ¿Qué es ese sonido? ¡Toda la cueva está temblando!",
  ui_story_31780601_73_dialog_content = "Tengo un mal presentimiento sobre esto. ¡Debe haber un monstruo terrible esperándonos más adelante!",
  ui_story_31780601_74_dialog_content = "¡No necesito habilidades psíquicas para saber que tenemos que salir de aquí rápidamente!",
  ui_story_31780601_75_dialog_content = "Espera. ¡Un monstruo así no aparecería sin motivo! ¡Debemos estar cerca del tesoro!",
  ui_story_31780601_76_dialog_content = "¿En serio sigues pensando en tesoros cuando tu vida está en juego?",
  ui_story_31780601_77_dialog_content = "Como dije, no tienes que preocuparte por nada mientras yo esté cerca.",
  ui_story_31780601_78_dialog_content = "¡Búho Lutumi!",
  ui_story_31780601_79_dialog_content = "¡Bul! ¡Bul-bul!",
  ui_story_31780601_80_dialog_content = "Bica!",
  ui_story_31780601_81_dialog_content = "¡Hai-hai!",
  ui_story_31780601_82_dialog_content = "¡Pequeña bola de pelo!",
  ui_story_31780601_83_dialog_content = "Chirrrrp-!",
  ui_story_31780601_84_dialog_content = "¡Transforma!",
  ui_story_31780601_85_dialog_content = "Chirrrrp-!",
  ui_story_31780601_86_dialog_content = "¡Vaya... Realmente vinieron!",
  ui_story_31780601_87_dialog_content = "Simplemente quédate detrás de mí y no tengas miedo, ¡yo te protegeré!",
  ui_story_31780601_88_dialog_content = "(Raro. ¿Por qué parece tan intenso de repente?)",
  ui_story_31780601_89_dialog_content = "¡Sigue avanzando—el tesoro está justo enfrente!",
  ui_story_31780601_90_dialog_content = "Oye, ¿qué es eso brillante en el suelo?",
  ui_story_31780601_91_dialog_content = "¡Oro! ¡Es oro!",
  ui_story_31780601_92_dialog_content = "Esa enorme mar de luz dorada brillando adelante... ¿Lo ves?!",
  ui_story_31780601_93_dialog_content = "¡Es el tesoro! ¡Vamos a por él!",
  ui_story_31780601_94_dialog_content = "Kree! Kree—!",
  ui_story_31780601_95_dialog_content = "¡¡¡Ahhhhh!!!",
  ui_story_31780601_96_dialog_content = "¿¡Uróboros!?",
  ui_story_31780601_97_dialog_content = "¿No se fue volando con Eulogoz? ¿Qué hace aquí?",
  ui_story_31780601_98_dialog_content = "¡Kree, kree—kree!",
  ui_story_31780601_99_dialog_content = "¡Guau!",
  ui_story_31780601_100_dialog_content = "¡Cuidado!",
  ui_story_31780601_101_dialog_content = "¡Ouroboros se llevó mi moneda de oro!",
  ui_story_31780601_102_dialog_content = "Está protegiendo este tesoro.",
  ui_story_31780601_103_dialog_content = "Extraño, nunca había escuchado nada sobre los Ouroboros teniendo una inclinación por acumular oro.",
  ui_story_31780601_104_dialog_content = "Parece que tendremos que derrotarlo antes de poder reclamar el tesoro.",
  ui_story_31780601_105_dialog_content = "¿Derrotar al Ouroboros? ¿Cómo vamos a hacer eso?",
  ui_story_31780601_106_dialog_content = "No digas más, los Ouroboros se han calmado un poco... Solo necesitamos aprovechar el momento adecuado...",
  ui_story_31780601_107_dialog_content = "Ni siquiera pienses en lastimarlo. Recuerdo que el Ouroboros era una criatura gentil y amable. No creo que nos ataque.",
  ui_story_31780601_108_dialog_content = "Quizás el tesoro ha corrompido su mente y se ha convertido en un demonio codicioso que arrebata tesoros...",
  ui_story_31780601_109_dialog_content = "¡Kree, kree!",
  ui_story_31780601_110_dialog_content = "Lutumi Owl, Bica, Gran Peludo, ¡derribenlo!",
  ui_story_31780601_111_dialog_content = "...",
  ui_story_31780601_112_dialog_content = "...",
  ui_story_31780601_113_dialog_content = "...",
  ui_story_31780601_114_dialog_content = "¡Oye! ¡No te atrevas!",
  ui_story_31780601_115_dialog_content = "¡Kree, kree—kree!",
  ui_story_31780601_116_dialog_content = "Oye, cálmate, cálmate... No estamos aquí para robar tu oro, amigo, solo estamos aquí para echar un vistazo... Oye, ¿quizás incluso podamos llegar a ser mejores amigos? ¿Qué dices?",
  ui_story_31780601_117_dialog_content = "¿Kree, kree?",
  ui_story_31780601_118_dialog_content = "¡Confía en mí! SOY el extrozoólogo más destacado de todo el continente; comunicarme con Ouroboros es una de mis innumerables fortalezas.",
  ui_story_31780601_119_dialog_content = "Kree—",
  ui_story_31780601_120_dialog_content = "Vamos, déjame darte un abrazo.",
  ui_story_31780601_121_dialog_content = "Vic, ¿qué crees que estás haciendo?",
  ui_story_31780601_122_dialog_content = "¡Mira de cerca! Estoy a punto de usar mis habilidades secretas de Encantador de Ouroboros—",
  ui_story_31780601_123_dialog_content = "El primer movimiento es la Postura del Pellizco en la Cara, donde uno usa ambas manos para acariciar la mejilla, ¡haciéndola sentir cálida al instante!",
  ui_story_31780601_124_dialog_content = "El segundo movimiento es el Paseo de Puntas, donde te paras de puntillas y caminas de un lado a otro en su espalda, ¡llevando incluso al más cauteloso Ouroboros a un estado de relajación!",
  ui_story_31780601_125_dialog_content = "No es común verte tomar algo tan en serio. Supongo que cuando hay un tesoro involucrado, realmente muestras un lado confiable.",
  ui_story_31780601_126_dialog_content = "¡Kree, kree, kree!",
  ui_story_31780601_127_dialog_content = "¿Ves cómo los ojos del Ouroboros se han estrechado? Eso significa que está empezando a sentirse extremadamente cómodo.",
  ui_story_31780601_128_dialog_content = "Kree!",
  ui_story_31780601_129_dialog_content = "¡¿Eh?! ¿Cómo se las arregló para convertirse en un huevo?",
  ui_story_31780601_130_dialog_content = "¿Quizás se sintió tan cómodo que se quedó dormido?",
  ui_story_31780601_131_dialog_content = "Entonces... ¿todo este oro es nuestro ahora?",
  ui_story_31780601_132_dialog_content = "Así es, puedes empacarlo y sacarlo de aquí.",
  ui_story_31780601_133_dialog_content = "¡Jajajajaja! ¡Finalmente tengo suficiente dinero para arreglar el Coloso! Hay suficiente aquí para cubrir todo el interior de Soroz con oro.",
  ui_story_31780601_134_dialog_content = "Vaya, ¿por dónde debería empezar las renovaciones? ¿El puente? ¿Los generadores? Tal vez debería construir una ampliación en mi habitación?",
  ui_story_31780601_135_dialog_content = "Sabes que no soy el tipo de chico que le gusta derrochar, pero no haría daño hacer mi habitación un poco más cómoda, ¿verdad?",
  ui_story_31780601_136_dialog_content = "Límpiate la boca, estás babeando.",
  ui_story_31780601_137_dialog_content = "Jejeje, lo siento, ¡supongo que me emocioné un poco demasiado!",
  ui_story_31780601_138_dialog_content = "¿Eh? ¿Por qué no recoges el oro? Has estado ahí parado mirándolo como si no lo quisieras.",
  ui_story_31780601_139_dialog_content = "Creo que ya es hora de que te despiertes.",
  ui_story_31780601_140_dialog_content = "¿Eh? ¿De qué estás hablando?",
  ui_story_31780601_141_dialog_content = "Lo que digo es... nada de esto es real... todo es una ilusión...",
  ui_story_31780601_142_dialog_content = "Err... Me duele la cabeza...",
  ui_story_31780601_143_dialog_content = "¡Pfffff! ¿Qué hace toda esta hierba en mi boca?!",
  ui_story_31780601_144_dialog_content = "Esa es la hierba que te salvó la vida, muchacho. Límpiate la boca ahora, toda la medicina se está saliendo.",
  ui_story_31780601_145_dialog_content = "Urgh... Yo... ¿Dónde estoy?",
  ui_story_31780601_146_dialog_content = "Estás en la balsa, ¡por supuesto! ¿Dónde más estarías?",
  ui_story_31780601_147_dialog_content = "¿La balsa? ¿Qué balsa?",
  ui_story_31780601_148_dialog_content = "¡La cosa de madera en la que estamos flotando ahora mismo! ¿Has perdido la memoria?",
  ui_story_31780601_149_dialog_content = "N-No... Recuerdo... Recuerdo que fuimos llevados a una cueva por medusas...",
  ui_story_31780601_150_dialog_content = "Oh, las medusas siguen aquí.",
  ui_story_31780601_151_dialog_content = "La cueva que mencionaste estaba llena de oro y custodiada por los Ouroboros, ¿verdad?",
  ui_story_31780601_152_dialog_content = "¡Sí! ¡Tú también estabas allí!",
  ui_story_31780601_153_dialog_content = "Nunca he estado en ese lugar, pero tú seguías gritando—",
  ui_story_31780601_154_dialog_content = "Dijiste que ibas a llevar todo el tesoro y cubrir todo el interior de Soroz con oro. Y algo sobre construir una ampliación en tu habitación. Sin duda, sonaba como un sueño maravilloso.",
  ui_story_31780601_155_dialog_content = "¿Un sueño? ¡No podría haber sido todo un sueño!",
  ui_story_31780601_156_dialog_content = "Todo es por culpa de la medusa, la Medusa Tejedora de Sueños. Tiene la habilidad de leer los pensamientos y emociones de quien la toque.",
  ui_story_31780601_157_dialog_content = "Poseen el poder de crear las visiones más perfectas o más horrendas en la mente de los afectados, basándose en sus miedos y deseos más profundos.",
  ui_story_31780601_158_dialog_content = "Entonces... ¿Mi deseo más profundo es... por oro?",
  ui_story_31780601_159_dialog_content = "¡Así es! Como el último Caelestite, todo en lo que puedes pensar es en oro, ¡sin una sola gran ambición o ideal elevado a la vista!",
  ui_story_31780601_160_dialog_content = "Erm... Bueno... yo solo...",
  ui_story_31780601_161_dialog_content = "¡Jeje! Solo somos tú y yo aquí, no necesitas explicarte conmigo.",
  ui_story_31780601_162_dialog_content = "Te entiendo totalmente. Si hubiera tocado esa cosa, probablemente habría tenido el mismo sueño.",
  ui_story_31780601_163_dialog_content = "Eso no es. No soy una persona codiciosa. ¡Ese sueño debe haber sido algún tipo de eructo cerebral!",
  ui_story_31780601_164_dialog_content = "¿Por qué más arriesgarías tu vida y tus extremidades para acompañarme en esta balsa endeble?",
  ui_story_31780601_165_dialog_content = "Me preocupaba que pudiera ser demasiado peligroso para ti zarpar completamente solo.",
  ui_story_31780601_166_dialog_content = "Entonces, ¿habrías venido conmigo si no hubiera tesoro por conseguir?",
  ui_story_31780601_167_option_content = "No me parece.",
  ui_story_31780601_168_dialog_content = "(Suspiro) Así que el tesoro del Rey Pirata realmente era solo una leyenda después de todo... Bueno, esa es la última vez que creo todo lo que leo en los libros ilustrados de Fia!",
  ui_story_31780601_169_dialog_content = "¿Conseguiste todo esto de un libro de cuentos para niños?!",
  ui_story_31780601_170_dialog_content = "Por cierto, no tengo absolutamente ninguna idea de en qué dirección estamos a la deriva en este momento.",
  ui_story_31780601_171_dialog_content = "Estaba haciendo todo lo posible para salvarte, así que naturalmente perdí la noción de hacia dónde nos llevaba la marea.",
  ui_story_31780601_172_dialog_content = "Necesitamos pensar en una forma de regresar a casa.",
  ui_story_31780601_173_dialog_content = "¿Algunas ideas?",
  ui_story_31780601_174_dialog_content = "Bueno, siempre está el método más primitivo pero más efectivo:",
  ui_story_31780601_175_dialog_content = "¡¡¡Ayuda!!!"
}
return config
